import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#1
  it('returns the missing required property without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
      async () => {
        calls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, calls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      calls: 0,
    });
  });
});
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#12
it('identifies the path of a nested missing required property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['city']}}},
    },
    async () => 'sunny'
  );

  const response = await registry.execute('weather', {address: {}});

  expect(response.result).toMatch(/\/address\/city.*required/);
});
